      "wizard.chk.agents.1.d": "GeDefense öffnet bewusst keine KI-Steuerschnittstelle ins Netz — kein Prompt-Injection- oder RCE-Risiko.",
      "wizard.chk.agents.2.t": "Lokaler SSH-/Agenten-Workflow",
      "wizard.chk.agents.2.d": "Kopiere oder lade AGENTS.md herunter und weise deinen CLI-Agenten an, Serverdienste, Ports & Module abzuwägen.",
      "wizard.chk.allow.1.t": "Eigene Admin-/SSH-/VPN-IPs eintragen",
      "wizard.chk.allow.1.d": "Bevor Kinetic XDP oder Lockdown blockieren, muss die Management-IP in der Allowlist synchronisiert sein.",
      "wizard.chk.allow.2.t": "Schutzphase gestaffelt schalten",
      "wizard.chk.allow.2.d": "Immer Observe -> Canary (Probezeit) -> Enforce fahren.",
      "wizard.chk.l7.1.t": "NGINX / Apache VGT auth_request einbinden",
      "wizard.chk.l7.1.d": "L7 Traffic Guard prüft HTTP-Traffic vor dem Webserver über den Unix-Socket-Hook.",
      "wizard.chk.l7.2.t": "CMS Shield für WordPress synchronisieren",
      "wizard.chk.l7.2.d": "WordPress-Seiten im CMS-View anbinden, um Login-/XMLRPC-Exploits direkt zu korrelieren.",
      "wizard.chk.webtls.1.t": "Modul A (Web Exposure): ELF & ALPN-Scan",
      "wizard.chk.webtls.1.d": "Erkennt NGINX/Apache/OLS Binaries inkl. http_v2/v3 & OpenSSL-Version sowie CVE-Erreichbarkeit.",
      "wizard.chk.webtls.2.t": "Modul B (Worker Integrity): Crash-Storm-Wächter",
      "wizard.chk.webtls.2.d": "Überwacht Worker-Abstürze (SIGSEGV/SIGBUS). Strict Cgroup nur bei isolierten Worker-Cgroups aktivieren.",
      "wizard.chk.webtls.3.t": "Modul C (TLS/ALPN Sensor): AF_PACKET + INET_DIAG",
      "wizard.chk.webtls.3.d": "Prüft ClientHello/ALPN/QUIC & H2 Control-Frame-Storms über gedefense-capture-helper.service.",
      "wizard.chk.lpe.1.t": "Modul D (LPE-Guard): Kernel Socket & ASLR-Härtung",
      "wizard.chk.lpe.1.d": "Blockiert unnötige Kernel-Socket-Familien (AF_TIPC, SCTP, DCCP, RDS) und erzwingt ASLR=2.",
      "wizard.chk.lpe.2.t": "Modul E (Edge-Proxy): Port-Kollisionen vermeiden",
      "wizard.chk.lpe.2.d": "Vor Aktivierung per ss prüfen, dass Listen (:8443) und Upstream (:8080) frei sind.",
      "wizard.chk.kin.1.t": "Kinetic XDP Driver / TC Ingress",
      "wizard.chk.kin.1.d": "Prüft Paketraten, Portscans und Velocity-Bursts direkt im eBPF/XDP-Datenpfad.",
      "wizard.chk.kin.2.t": "Signierte Threat Feeds & Auto-Sync",
      "wizard.chk.kin.2.d": "Lädt lokale verifizierte Sperrlisten ohne Cloud-Abhängigkeit in die Kernel-Map.",
      "wizard.chk.xdr.1.t": "XDR Verhaltensprofile anlernen (Warmup)",
      "wizard.chk.xdr.1.d": "XDR zunächst in Observe warmlaufen lassen, bevor Enforce aktiviert wird.",
      "wizard.chk.xdr.2.t": "StyX Egress-Wächter",
      "wizard.chk.xdr.2.d": "Erkennt periodische C2-Beacons & unerwartete Ausbrüche aus Web-/PHP-Cgroups.",
      "wizard.chk.xdr.3.t": "Titan Exec-Gate",
      "wizard.chk.xdr.3.d": "Verhindert nicht autorisierte Binärausführung / memfd-Payloads via Kernel LSM.",
      "wizard.chk.cells.1.t": "Parser Cells Sandbox",
      "wizard.chk.cells.1.d": "Entkoppelt riskante Datei-Parser in isolierte Zellen (gedefense-cell-helper).",
      "wizard.chk.cells.2.t": "FIM Baseline aktuell halten",
      "wizard.chk.cells.2.d": "Nach Paket-Updates oder gewollten Systemänderungen im Integrity-View Baseline neu bestätigen.",
      "wizard.chk.wit.1.t": "Boot Trust & IMA/TPM Attestierung",
      "wizard.chk.wit.1.d": "Prüft Kernel-Lockdown, SecureBoot und Signatur-Integrität des Hosts.",
      "wizard.chk.wit.2.t": "Out-of-Band Witness",
      "wizard.chk.wit.2.d": "Sichert signierte Checkpoints extern zur Erkennung von Log-Manipulation.",
      "wizard.chk.wit.3.t": "Emergency Lockdown",
      "wizard.chk.wit.3.d": "Letzte Schutzstufe bei bestätigtem Vorfall mit Cooldown und getippter Bestätigung."

